/**
 * A real place that has no ZIP of its own and mails under another town's.
 * `name` is the place as it should be recorded; `postalCity` is the registry
 * city whose ZIP serves it.
 *
 * These are NOT misspellings -- they are usually a different municipality.
 * Newington NH mails as Portsmouth 03801, but the work is in Newington, and
 * that is the unit territory reporting counts. So the parser keeps the typed
 * name and uses `postalCity` only to reach the county (for the ZIP-conflict
 * check) and the ZIP (when deriving one from a town with no ZIP given).
 *
 * Sourced from the USPS *acceptable* city list. Entries that are themselves a
 * registry city in the same state are omitted -- that city's own record
 * already resolves them exactly.
 */
export type PlaceName = { name: string; postalCity: string };

